// Renders a card as a map of Africa with the card's country highlighted.
// map.svg is generated by tools/make-africa-map.mjs.
const SVG_NS = 'http://www.w3.org/2000/svg';

export async function create(stage, { assetUrl }) {
  const text = await (await fetch(assetUrl('map.svg'))).text();
  const doc = new DOMParser().parseFromString(text, 'image/svg+xml');
  const svg = document.importNode(doc.documentElement, true);
  svg.classList.add('fc-map');
  svg.setAttribute('role', 'img');
  svg.setAttribute('aria-label', 'Map of Africa with one country highlighted');
  const markers = document.createElementNS(SVG_NS, 'g');
  svg.append(markers);
  stage.replaceChildren(svg);

  function mark(id, cls) {
    const g = svg.querySelector(`g[data-id="${id}"]`);
    if (!g) return;
    g.classList.add(cls);
    // Tiny countries get a ring so they're findable.
    if (g.dataset.small) {
      const c = document.createElementNS(SVG_NS, 'circle');
      c.setAttribute('cx', g.dataset.cx);
      c.setAttribute('cy', g.dataset.cy);
      c.setAttribute('r', 16);
      c.setAttribute('class', `fc-marker ${cls}`);
      markers.append(c);
    }
  }

  function clear() {
    svg.querySelectorAll('g.target, g.picked').forEach((g) => g.classList.remove('target', 'picked'));
    markers.replaceChildren();
  }

  return {
    show(card) {
      clear();
      mark(card.id, 'target');
    },
    reveal(card, { picked } = {}) {
      if (picked && picked !== card.id) mark(picked, 'picked');
    },
  };
}
